package com.ekzellence.watch;
import fi.iki.elonen.NanoHTTPD;
import android.net.Uri;
import android.os.ParcelFileDescriptor;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import org.json.*;

public class WatchServer extends NanoHTTPD {
 final WatchService owner;final Security security;
 final Map<String,Login> logins=new ConcurrentHashMap<>();
 final Map<String,Attempt> attempts=new ConcurrentHashMap<>();
 final java.util.concurrent.Semaphore clipping=new java.util.concurrent.Semaphore(1);
 static class Login{String csrf;long seen;Login(String c){csrf=c;seen=System.currentTimeMillis();}}
 static class Attempt{int n;long until;}
 WatchServer(WatchService s)throws Exception{super(8443);owner=s;security=s.security;makeSecure(security.tls().getServerSocketFactory(),new String[]{"TLSv1.2","TLSv1.3"});}
 Response json(Response.Status status,JSONObject j){Response r=newFixedLengthResponse(status,"application/json; charset=utf-8",j.toString());headers(r);return r;}
 JSONObject obj(String key,Object value)throws JSONException{return new JSONObject().put(key,value);}
 void headers(Response r){r.addHeader("Cache-Control","no-store");r.addHeader("X-Content-Type-Options","nosniff");r.addHeader("X-Frame-Options","DENY");r.addHeader("Referrer-Policy","no-referrer");r.addHeader("Content-Security-Policy","default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' blob:; media-src 'self' blob:; connect-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'");}
 String cookie(IHTTPSession s){String h=s.getHeaders().getOrDefault("cookie","");for(String c:h.split(";")){String[] p=c.trim().split("=",2);if(p.length==2&&p[0].equals("watch"))return p[1];}return "";}
 Login login(IHTTPSession s){String token=cookie(s);Login l=logins.get(token);if(l!=null){if(System.currentTimeMillis()-l.seen>1800000){logins.remove(token);return null;}l.seen=System.currentTimeMillis();}return l;}
 Response signedIn(){String token=security.random();Login l=new Login(security.random());if(logins.size()>100)logins.clear();logins.put(token,l);try{Response r=json(Response.Status.OK,obj("csrf",l.csrf));r.addHeader("Set-Cookie","watch="+token+"; Path=/; HttpOnly; Secure; SameSite=Strict");return r;}catch(Exception e){return newFixedLengthResponse(Response.Status.INTERNAL_ERROR,"text/plain","Login failed");}}
 boolean local(IHTTPSession s){return s.getRemoteIpAddress().equals("127.0.0.1")||s.getRemoteIpAddress().equals("::1")||s.getRemoteIpAddress().equals("0:0:0:0:0:0:0:1");}
 JSONObject body(IHTTPSession s)throws Exception{String len=s.getHeaders().getOrDefault("content-length","0");if(Long.parseLong(len)<1||Long.parseLong(len)>16384||s.getHeaders().containsKey("transfer-encoding"))throw new IOException("Request too large");if(!s.getHeaders().getOrDefault("content-type","").startsWith("application/json"))throw new IOException("JSON required");String origin=s.getHeaders().get("origin");if(origin!=null&&!origin.equals("https://"+s.getHeaders().get("host")))throw new IOException("Invalid origin");Map<String,String> files=new HashMap<>();s.parseBody(files);return new JSONObject(files.getOrDefault("postData","{}"));}
 String param(IHTTPSession s,String k,String fallback){List<String> v=s.getParameters().get(k);return v==null||v.isEmpty()?fallback:v.get(0);}
 @Override public Response serve(IHTTPSession s){try{String path=s.getUri();boolean post=s.getMethod()==Method.POST;
 if(s.getMethod()!=Method.GET&&s.getMethod()!=Method.HEAD&&!post)return json(Response.Status.METHOD_NOT_ALLOWED,obj("error","Unsupported method"));
 if(!post&&(path.equals("/")||path.equals("/ui.js")||path.equals("/style.css"))){String asset=path.equals("/")?"index.html":path.substring(1);InputStream in=owner.getAssets().open(asset);Response r=newChunkedResponse(Response.Status.OK,asset.endsWith("js")?"text/javascript":asset.endsWith("css")?"text/css":"text/html; charset=utf-8",in);headers(r);return r;}
 if(path.equals("/meta")&&!post)return json(Response.Status.OK,new JSONObject().put("configured",security.configured()).put("local",local(s)));
 if(path.equals("/setup")&&post){JSONObject b=body(s);if(!local(s))return json(Response.Status.FORBIDDEN,obj("error","Create the password on the tablet"));security.setup(b.optString("password"));return signedIn();}
 if(path.equals("/login")&&post){JSONObject b=body(s);String ip=s.getRemoteIpAddress();long now=System.currentTimeMillis();Attempt a=attempts.computeIfAbsent(ip,k->new Attempt());synchronized(a){if(now<a.until)return json(Response.Status.FORBIDDEN,obj("error","Too many attempts. Wait one minute."));if(!security.verify(b.optString("password"))){a.n++;if(a.n>=5){a.until=now+60000;a.n=0;}return json(Response.Status.UNAUTHORIZED,obj("error","Incorrect password"));}a.n=0;a.until=0;}if(attempts.size()>200)attempts.clear();return signedIn();}
 Login l=login(s);if(l==null)return json(Response.Status.UNAUTHORIZED,obj("error","Please sign in"));
 if(path.equals("/auth")&&!post)return json(Response.Status.OK,obj("csrf",l.csrf));
 JSONObject b=null;if(post){if(!l.csrf.equals(s.getHeaders().get("x-watch-csrf")))return json(Response.Status.FORBIDDEN,obj("error","Please sign in again"));b=body(s);}
 if(path.equals("/logout")&&post){logins.remove(cookie(s));Response r=json(Response.Status.OK,obj("ok",true));r.addHeader("Set-Cookie","watch=; Path=/; Max-Age=0; HttpOnly; Secure; SameSite=Strict");return r;}
 if(path.equals("/state")&&!post)return json(Response.Status.OK,owner.state());
 if(path.equals("/camera")&&post){String id=b.optString("id","");if(owner.isEnabled(id))throw new IOException("Stop the camera before editing");return json(Response.Status.OK,obj("id",owner.store.saveCamera(b)));}
 if(path.equals("/toggle")&&post){owner.toggle(b.getString("id"),b.getBoolean("enabled"));return json(Response.Status.OK,obj("ok",true));}
 if(path.equals("/cloud")&&post){if(b.optBoolean("enabled")){String url=b.getString("url");URIcheck(url);String token=b.getString("token");if(token.length()<24)throw new IOException("Cloud token must be at least 24 characters");owner.store.prefs.edit().putString("cloudUrl",url.replaceAll("/+$","")).putString("cloudToken",security.encrypt(token)).putBoolean("cloudEnabled",true).commit();}else owner.store.prefs.edit().putBoolean("cloudEnabled",false).commit();return json(Response.Status.OK,obj("ok",true));}
 if(path.equals("/recordings")&&!post){String camera=param(s,"camera","");long since=Long.parseLong(param(s,"since","0")),until=Long.parseLong(param(s,"until","9223372036854775807"));return json(Response.Status.OK,obj("recordings",owner.store.recordings(camera,since,until)));}
 if(path.equals("/frame")&&!post){String id=param(s,"camera","usb");byte[] f=owner.frames.get(id);if(f==null||!owner.isEnabled(id)||System.currentTimeMillis()-owner.frameTimes.getOrDefault(id,0L)>5000)return json(Response.Status.NOT_FOUND,obj("error","Waiting for live image"));Response r=newFixedLengthResponse(Response.Status.OK,"image/jpeg",new ByteArrayInputStream(f),f.length);headers(r);return r;}
 if(path.equals("/video")&&!post){long id=Long.parseLong(param(s,"id","0"));Uri uri=owner.store.recording(id);return file(s,uri,"camera-"+id+".mp4",param(s,"download","0").equals("1"));}
 if(path.equals("/clip")&&post){if(!clipping.tryAcquire())return json(Response.Status.SERVICE_UNAVAILABLE,obj("error","Another clip is exporting"));try{long id=b.getLong("id");File f=Clipper.clip(owner,owner.store.recording(id),(long)(b.getDouble("from")*1000000),(long)(b.getDouble("to")*1000000));InputStream in=new FilterInputStream(new FileInputStream(f)){public void close()throws IOException{try{super.close();}finally{f.delete();}}};Response r=newFixedLengthResponse(Response.Status.OK,"video/mp4",in,f.length());headers(r);r.addHeader("Content-Disposition","attachment; filename=\"clip-"+id+".mp4\"");return r;}finally{clipping.release();}}
 return json(Response.Status.NOT_FOUND,obj("error","Not found"));
 }catch(Exception e){try{return json(Response.Status.BAD_REQUEST,obj("error",e.getMessage()==null?"Request failed":e.getMessage()));}catch(Exception ignored){return newFixedLengthResponse(Response.Status.INTERNAL_ERROR,"text/plain","Request failed");}}}
 void URIcheck(String url)throws Exception{java.net.URI u=new java.net.URI(url);if(!"https".equals(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null||u.getQuery()!=null)throw new IOException("Cloud endpoint must be an HTTPS URL without credentials or query");}
 Response file(IHTTPSession s,Uri uri,String name,boolean download)throws Exception{long size=owner.store.size(uri);if(size<=0)throw new FileNotFoundException("Recording unavailable; check SD card");long start=0,end=size-1;boolean partial=false;String range=s.getHeaders().get("range");if(range!=null){try{if(!range.matches("bytes=\\d*-\\d*"))throw new Exception();String[] p=range.substring(6).split("-",-1);if(p[0].isEmpty()){long n=Long.parseLong(p[1]);if(n<=0)throw new Exception();start=Math.max(0,size-n);}else{start=Long.parseLong(p[0]);if(!p[1].isEmpty())end=Math.min(size-1,Long.parseLong(p[1]));}if(start<0||start>=size||end<start)throw new Exception();partial=true;}catch(Exception e){Response r=newFixedLengthResponse(Response.Status.RANGE_NOT_SATISFIABLE,"text/plain","");r.addHeader("Content-Range","bytes */"+size);headers(r);return r;}}
 InputStream in;if(uri.getScheme().equals("file"))in=new FileInputStream(new File(uri.getPath()));else{ParcelFileDescriptor p=owner.getContentResolver().openFileDescriptor(uri,"r");if(p==null)throw new IOException("File unavailable");in=new ParcelFileDescriptor.AutoCloseInputStream(p);}long skipped=0;while(skipped<start){long n=in.skip(start-skipped);if(n==0){if(in.read()<0){in.close();throw new IOException("Truncated recording");}n=1;}skipped+=n;}Response r=newFixedLengthResponse(partial?Response.Status.PARTIAL_CONTENT:Response.Status.OK,"video/mp4",in,end-start+1);headers(r);r.addHeader("Accept-Ranges","bytes");if(partial)r.addHeader("Content-Range","bytes "+start+"-"+end+"/"+size);if(download)r.addHeader("Content-Disposition","attachment; filename=\""+name+"\"");return r;}
}
